import assert from "node:assert/strict";
import fs from "node:fs";
import test from "node:test";

import { plan } from "./model.mjs";

const night = JSON.parse(fs.readFileSync(new URL("./night.json", import.meta.url)));
const close = (actual, expected, tolerance = 1e-7) => {
  assert.ok(
    Math.abs(actual - expected) <= tolerance,
    `expected ${expected}, got ${actual}`,
  );
};

function caps(buildingKw) {
  return buildingKw.map((load) =>
    Math.max(0, Math.min(night.chargerKw, night.siteLimitKw - load)),
  );
}

function batteryGain(scenario, bus) {
  let acEnergy = 0;
  for (let slot = bus.fromSlot; slot < bus.untilSlot; slot += 1) {
    acEnergy += scenario.acKw[slot] * night.slotHours;
  }
  return acEnergy * night.efficiency;
}

function assertPhysical(scenario, buildingKw, efficiency = night.efficiency) {
  assert.equal(scenario.acKw.length, night.slotStart.length);
  const limits = caps(buildingKw);

  scenario.acKw.forEach((power, slot) => {
    assert.ok(power >= 0);
    assert.ok(power <= limits[slot] + 1e-7);
    assert.ok(buildingKw[slot] + power <= night.siteLimitKw + 1e-7);
    const inWindow = night.buses.some(
      (bus) => slot >= bus.fromSlot && slot < bus.untilSlot,
    );
    if (!inWindow) close(power, 0);
  });

  for (const bus of night.buses) {
    let acEnergy = 0;
    for (let slot = bus.fromSlot; slot < bus.untilSlot; slot += 1) {
      acEnergy += scenario.acKw[slot] * night.slotHours;
    }
    const endKwh = bus.startKwh + acEnergy * efficiency;
    assert.ok(endKwh <= bus.capacityKwh + 1e-7);
    assert.ok(endKwh <= Math.max(bus.requiredKwh, bus.startKwh) + 1e-7);
  }
}

test("90%: normal is feasible, cold needs exactly 20 kW moved, shifted is feasible", () => {
  const result = plan(night, 0.9);

  assert.deepEqual(result.normal, {
    acKw: [80, 40, 70, 50],
    feasible: true,
  });
  assert.deepEqual(result.cold, {
    acKw: [80, 20, 70, 50],
    feasible: false,
  });
  assert.deepEqual(result.shifted, {
    acKw: [80, 40, 70, 50],
    feasible: true,
  });
  assert.equal(result.minShiftKw, 20);

  assertPhysical(result.normal, night.buildingKw);
  assertPhysical(
    result.cold,
    night.buildingKw.map((load, slot) => load + night.coldExtraKw[slot]),
  );
  assertPhysical(result.shifted, [40, 80, 50, 70]);

  const [busA, busB] = night.buses;
  close(busA.startKwh + batteryGain(result.shifted, busA), 126);
  close(busB.startKwh + batteryGain(result.shifted, busB), 130);
});

test("unshifted cold gap is 9 kWh on bus A; B can cover its own departure", () => {
  const result = plan(night, 0.9);
  const [busA, busB] = night.buses;

  close(busA.startKwh + batteryGain(result.cold, busA), 117);
  close(126 - (busA.startKwh + batteryGain(result.cold, busA)), 9);
  close(busB.startKwh + batteryGain(result.cold, busB), 130);
});

test("85%: the shift cannot repair either scenario; optimum balance still leaves 3 kWh per bus", () => {
  const result = plan(night, 0.85);
  const [busA, busB] = night.buses;

  assert.equal(result.normal.feasible, false);
  assert.equal(result.cold.feasible, false);
  assert.equal(result.shifted, null);
  assert.equal(result.minShiftKw, null);

  assertPhysical(result.normal, night.buildingKw, 0.85);
  assertPhysical(
    result.cold,
    night.buildingKw.map((load, slot) => load + night.coldExtraKw[slot]),
    0.85,
  );

  close(busA.startKwh + batteryGain(result.normal, busA), 123);
  close(busA.startKwh + batteryGain(result.cold, busA), 114.5);
  close(busB.startKwh + batteryGain(result.cold, busB), 130);
});

test("90% is the exact breakpoint: just above works, just below does not", () => {
  const above = plan(night, 0.900001);
  const below = plan(night, 0.899999);

  assert.equal(above.shifted.feasible, true);
  assert.ok(above.minShiftKw < 20);
  assert.ok(above.minShiftKw > 19.99);

  assert.equal(below.normal.feasible, false);
  assert.equal(below.shifted, null);
  assert.equal(below.minShiftKw, null);
});

test("plan does not mutate the input and defaults to night.efficiency", () => {
  const snapshot = JSON.stringify(night);
  const result = plan(night);

  assert.equal(JSON.stringify(night), snapshot);
  assert.equal(result.minShiftKw, 20);
});

